ation warning was printed. Starting in Node.js 8.0.0, calling crypto.pbkdf2() or crypto.pbkdf2Sync() with digest set to undefined will throw a TypeError.\"},{\"charStart\":5283,\"charEnd\":5326,\"text\":\"DEP0010: crypto.createCredentials\\n#\\nHistory\"},{\"charStart\":5442,\"charEnd\":5479,\"text\":\"DEP0011: crypto.Credentials\\n#\\nHistory\"},{\"charStart\":5581,\"charEnd\":5614,\"text\":\"DEP0012: Domain.dispose\\n#\\nHistory\"},{\"charStart\":5766,\"charEnd\":5826,\"text\":\"DEP0013: fs asynchronous function without callback\\n#\\nHistory\"},{\"charStart\":5993,\"charEnd\":6043,\"text\":\"DEP0014: fs.read legacy String interface\\n#\\nHistory\"},{\"charStart\":6064,\"charEnd\":6178,\"text\":\"The fs.read() legacy String interface is deprecated. Use the Buffer API as mentioned in the documentation instead.\"},{\"charStart\":6180,\"charEnd\":6234,\"text\":\"DEP0015: fs.readSync legacy String interface\\n#\\nHistory\"},{\"charStart\":6255,\"charEnd\":6373,\"text\":\"The fs.readSync() legacy String interface is deprecated. Use the Buffer API as mentioned in the documentation instead.\"},{\"charStart\":6375,\"charEnd\":6405,\"text\":\"DEP0016: GLOBAL/root\\n#\\nHistory\"},{\"charStart\":6426,\"charEnd\":6539,\"text\":\"The GLOBAL and root aliases for the global property were deprecated in Node.js 6.0.0 and have since been removed.\"},{\"charStart\":6541,\"charEnd\":6547,\"text\":\"DEP001\"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-9fdeb337-f0f5-4f2f-8446-7da42141df40\\\\profile\\\\conversations\\\\68660e8fd739c36111f8ef8ffd451ef2fcf59726e93f41a61e38e92b3b0b751d\\\\session-b75589f2-2dd3-47de-9e72-3945321ae904\\\\.weftmate-web-sources\\\\capture-af7345b0-33d0-4a72-948b-cd10a12d94fd.txt\"}"
